---GetMessageIdByTargetId 通过目标ID获取短信ID
---@param talkCountId string 话题ID
---@param catId string 角色ID
function PhoneUtils.GetMessageIdByTargetId(talkCountId, targetId)
    talkCountId = checkString(talkCountId)
    targetId = checkString(targetId)

    local tableName
    if PhoneUtils.IsTalkCountIsMessage(talkCountId) then
        tableName = string.format("%sContrast", AutoIds.IdSetting861)
    else
        tableName = string.format("%sContrast", AutoIds.IdSetting860)
    end 

    local id = CfUtils.GetStringIdGroupData(tableName, talkCountId.."_"..targetId)
    return id
end

---GetMessageIdByTargetId 通过目标ID获取短信vo
---@param targetId string 短信的目标ID
---@param talkCountId string 话题ID
function PhoneUtils.GetMessageVoByTargetId(talkCountId, targetId)
    local id = PhoneUtils.GetMessageIdByTargetId(talkCountId, targetId)
    if not id then 
        return nil
    end 

    local vo
    if PhoneUtils.IsTalkCountIsMessage(talkCountId) then
        vo = PhoneUtils.GetPhoneMessageVo(id)
    else
        vo = PhoneUtils.GetPhoneTelephoneVo(id)
    end 

    return vo
end

---GetTalkContentIds 获取该角色所有的话题id
---@param catId string @ 角色id
---@param type Constants.PhoneTalkContentType @ 类型 电话/短信
---@return integer[]
function PhoneUtils.GetTalkContentIds(catId, type)
    local key
    if checkNumber(type) == Constants.PhoneTalkContentType.Message then
        key = "messageId"
    elseif checkNumber(type) == Constants.PhoneTalkContentType.Telephone then
        key = "telephoneId"
    end
    local ids = CfUtils.GetIdGroupData(AutoIds.IdSetting862, catId, key)
    return ids
end

---GetUnlockTalkContentIds 获取该角色已解锁未完成的所有的话题id
---@param catId string @ 角色id
---@param type Constants.PhoneTalkContentType @ 类型 电话/短信
---@return string[]
function PhoneUtils.GetUnlockTalkContentIds(catId, type)
    local t = {}
    local allContentId = PhoneUtils.GetTalkContentIds(catId, type)
    if not allContentId then
        return t
    end
    for k, v in pairs(allContentId) do
        if PhoneUtils.IsUnlockTalkContent(checkString(v)) and not PhoneUtils.IsPassTalkContent(checkString(v)) then
            table.insert(t, checkString(v))
        end
    end
    return t
end

---GetTalkIds 获取该话题所有的对话顺序id
---@param id string 话题id
function PhoneUtils.GetTalkIds(id)
    local vo = PhoneUtils.GetPhoneTalkContentVo(id)
    local ids
    if vo then
        --短信
        if checkNumber(vo.topicType) == Constants.PhoneTalkContentType.Message then
            ids = CfUtils.GetIdGroupData(AutoIds.IdSetting861, id)
        --电话
        elseif checkNumber(vo.topicType) == Constants.PhoneTalkContentType.Telephone then
            ids = CfUtils.GetIdGroupData(AutoIds.IdSetting860, id)
        end
    end
    return ids
end

