---GetTalkContentSourceName 获取话题来源名字
---@param talkContentId string 话题id
function PhoneUtils.GetTalkContentSourceName(talkContentId)
    local vo = PhoneUtils.GetPhoneTalkContentVo(talkContentId)
    if not vo then
        return ""
    end
    local source = checkNumber(vo.source)
    local str = ""
    if source == 1 then
        str = localize("卡牌")
    elseif source == 2 then
        str = localize("主线")
    elseif source == 3 then
        str = localize("好感度")
    elseif source == 4 then
        str = localize("日常")
    end
    return str
end

