---IsCatHasNewTalkCount  该角色是否有新话题
---@param id string 话题id
function PhoneUtils.IsCatHasNewTalkCount(catId)
    local t = GameUtils.GetRedPointLocalAllGoods(Constants.RedPointLocalKey.Goodkey, Constants.IDType.PhoneTalkContent)
    --如果有话题
    if table.count(t) > 0 then
        for k, v in pairs(t) do
            local vo = PhoneUtils.GetPhoneTalkContentVo(v)
            if vo then
                if checkNumber(vo.character) == checkNumber(catId) then 
                    return true
                end
            end
        end
    end
    return false
end

---IsTalkCountIsNew  该话题是否为新
---@param talkCountId string 话题id
function PhoneUtils.IsTalkCountIsNew(talkCountId)
    local t = GameUtils.GetRedPointLocalAllGoods(Constants.RedPointLocalKey.Goodkey, Constants.IDType.PhoneTalkContent)
    --如果有话题
    if table.count(t) > 0 then
        for k, v in pairs(t) do
            if checkNumber(v) == checkNumber(talkCountId) then 
                return true
            end
        end
    end
    return false
end

