---GetCatFavorabilityLevel 获取好感度等级 和总经验
---@param catId string 角色id
---@param exp string 经验值
function PhoneUtils.GetCatFavorabilityLevel(catId)
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
    local oldLevel, oldExp = comp:GetCatFavorabilityLevel(catId)
    return oldLevel, oldExp
end

---GetCatFavorabilityLevelAndCurExp 获取好感度等级 和当前经验
---@param catId string 角色id
---@param exp string 经验值
function PhoneUtils.GetCatFavorabilityLevelAndCurExp(catId)
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
    local oldLevel, oldExp = comp:GetCatFavorabilityLevel(catId)
     
    if oldLevel > 1 then
        for i = 1, oldLevel do
            local vo = PhoneUtils.GetLikabilityLevelVo(i)
            if vo then
                local targetLevelExp = checkNumber(vo.experience)
                oldExp = oldExp - targetLevelExp
            end
        end
    end
    return oldLevel, oldExp
end

