---GetRoleCurCardSkin 获取当前角色的卡牌形象
---@param catId string 角色id
function PhoneUtils.GetRoleCurCardSkinId(catId)
    local catDojo = PhoneUtils.GetCatDojoById(catId)
    if catDojo then
        local cardId = checkNumber(catDojo.cardId)
        --如果还没设置  取一张已拥有的卡牌id返回
        if cardId == 0 then
            local vo = PhoneUtils.GetPhoneRoleVisitingVo(catId)
            if vo then
                return vo.cardSkinId
            end
        else
            return cardId
        end
    else
        local vo = PhoneUtils.GetPhoneRoleVisitingVo(catId)
        if vo then
            return vo.cardSkinId
        end
    end
    return nil
end

---GetRoleCurName 获取当前角色的名字
---@param catId string 角色id
function PhoneUtils.GetRoleCurName(catId)
    local catDojo = PhoneUtils.GetCatDojoById(catId)
    if catDojo then
        local cardName = checkString(catDojo.name)
        local vo = PhoneUtils.GetCatVo(catId)
        local autoName = ""
        if vo then
            autoName = vo.name
        end
        --说明没设置
        if cardName == "" then
            return autoName, autoName
        else
            return cardName, autoName
        end
    end

    return "", ""
end

---GetCatCurSign 获取角色当前的签名
---@param id string 角色id
function PhoneUtils.GetCatCurSign(id)
    local vo = PhoneUtils.GetPhoneRoleVisitingVo(id)
    if not vo then 
        return ""
    end
    --是否已解锁
    local isUnlock = GameUtils.IsUnlocked(checkString(vo.unlockType), checkString(vo.unlockNum), checkString(vo.unlockId))
    if isUnlock then
        return vo.text
    end

    return ""
end

