---IsHasNotDrawReward 是否有角色有未领取的奖励
function PhoneUtils.IsHasNotDrawReward()
    local cats = PhoneUtils.GetAllUnlockCatIdArray()
    if cats then
        for k, v in pairs(cats) do
            if PhoneUtils.IsCatHasNotDrawReward(v) then
                return true
            end
        end
    end
    return false
end

---IsCatHasNotDrawReward 改角色是否有未领取的奖励
---@param catId string 角色id
function PhoneUtils.IsCatHasNotDrawReward(catId)
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting865, catId)
    if not t then
        return false
    end

    for k, v in pairs(t) do
        if PhoneUtils.IsCanDrawRewardById(v) and not PhoneUtils.IsDrawRewardById(v) then
            return true
        end
    end
    return false
end

---IsDrawRewardById 是否领取了该奖励
---@param rewardId string 奖励id
function PhoneUtils.IsDrawRewardById(rewardId)
    rewardId = checkString(rewardId)
    local vo = PhoneUtils.GetLikabilityRewardVo(rewardId)
    if not vo then
        return false
    end
    local catDojo = PhoneUtils.GetCatDojoById(vo.character)
    if not catDojo then
        return false
    end

    local t = checkTable(catDojo.favorabilityRewards)
    for k, v in pairs(t) do
        if checkNumber(v) == checkNumber(rewardId) then
            return true
        end
    end

    return false
end

---IsCanDrawRewardById 是否可以领取该奖励
---@param rewardId string 奖励id
function PhoneUtils.IsCanDrawRewardById(rewardId)
    local vo = PhoneUtils.GetLikabilityRewardVo(rewardId)
    if not vo then
        return false
    end

    local level, exp = PhoneUtils.GetCatFavorabilityLevel(vo.character)
    return checkNumber(level) >= checkNumber(vo.rankId)
end

---GetAllUnlockCatId 获取所有解锁的角色id数组
function PhoneUtils.GetAllUnlockCatIdArray()
    local phoneComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
    local allCats = phoneComp:GetAllCats()
    local t = {}
    if not allCats then
        return t
    end
    for k, v in pairs(allCats) do
        if PhoneUtils.IsUnlockCatById(k) then
            table.insert(t, checkString(k))
        end
    end
    table.sort(t, function(a, b)
        return checkNumber(a) < checkNumber(b)
    end)
    return t
end

---GetAllCats 获取所有的角色id数组
function PhoneUtils.GetAllCatIdArray()
    local phoneComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
    local allCats = phoneComp:GetAllCatIdArray()
    table.sort(allCats, function(a, b)
        return checkNumber(a) < checkNumber(b)
    end)
    return allCats
end

---IsUnlockCatById 是否解锁该角色
---@param catId string 角色id
function PhoneUtils.IsUnlockCatById(catId)
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
    local t = checkTable(comp:GetAllCardTable())    

    for k, v in pairs(t) do
        local vo = CardConfMgr:GetInstance():GetCardByRefId(v.cardId) 
        if vo then
            if checkNumber(vo.characterId) == checkNumber(catId) then
                return true
            end
        end
    end
    return false
end 

--获取某个等级的奖励数据
function PhoneUtils.GetLikabilityRewardDatas(catId, level)
    local vo = PhoneUtils.GetLikabilityRewardVo(PhoneUtils.GetLikabilityRewardId(catId, level))
    local t = {}
    if not vo then
        return t
    end
    t.quest = checkNumber(vo.questId)
    t.voice = checkNumber(vo.voice)
    t.news = checkNumber(vo.news)
    t.items = {}
    local items = CfUtils.Split(vo.itemId)
    if items then
        local rewards = {}
        for k, v in pairs(items) do
            if checkNumber(v) > 0 then
                table.insert(rewards, {
                    goodsId = checkNumber(v),
                    num = 0,
                })
            end
        end
        t.items = rewards
    end
    return t
end

