    local num = PhoneUtils.GetPhoneGiftGradeUpNum(giftId)
    local vo = PhoneUtils.GetPhoneGiftPackUpVo(packId)
    if vo then
        num = num * checkNumber(vo.addition)
    end
    return checkInt(num)
