---@param packId string 包装id
function PhoneUtils.GetPhoneGiftAndPackGradeUpNum(giftId, packId)
    local num = PhoneUtils.GetPhoneGiftGradeUpNum(giftId)
    local vo = PhoneUtils.GetPhoneGiftPackUpVo(packId)
    if vo then
        num = num + num * checkNumber(vo.addition)
    end
    return checkInt(num)
end

---GetCatCurSelectGifts 获取角色当前的可以送的礼物
---@param catId string 角色id
function PhoneUtils.GetCatCurSelectGifts(catId)
    local dojo = PhoneUtils.GetCatDojoById(catId)
    if dojo then
        local t = {}
        for k, v in pairs(checkTable(dojo.gift)) do
            table.insert(t, checkString(v))
        end
        table.sort(t, function(a, b)
            return checkNumber(PhoneUtils.GetPhoneGiftGrade(a)) < checkNumber(PhoneUtils.GetPhoneGiftGrade(b))
        end)
        return t
    end
    return nil
end

