---GetAllGiveGiftNum 获取所有的送礼次数  
function PhoneUtils.GetAllGiveGiftNum()
    local storeComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.StoreComponent)
    local StoreConstants = import('Game.UI.Store.StoreConstants')

    local allGiveGiftNum = 0
    local vo = PhoneUtils.GetPhoneParameterVo("1")
    if vo then
        allGiveGiftNum = checkNumber(vo.num)
    end
    allGiveGiftNum = allGiveGiftNum + checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.GiftNum))
    return allGiveGiftNum
end


