---GetCatFinishChatInfo 获取一个短信的选择数据
---@param index number 选择下标
---@param messageId string 短信id
---@param isChat boolean 是否时聊天
function PhoneUtils.GetMessageSelection(messageId, index, isChat)
    index = checkNumber(index)
    local data = {}
    data.index = index            --回复下标
    data.sourceMessageId = checkString(messageId)      --回复的信息id

    local vo 
    if isChat then
        vo = PhoneUtils.GetPhoneChattingVo(messageId) 
    else
        vo = PhoneUtils.GetPhoneMessageVo(messageId) 
    end    
    if not vo then
        return data
    end

    if index == 1 then
        data.targetId = checkString(vo.choiceOneId)       --该选择指向的id
        data.name = checkString(vo.choiceOne)
    elseif index == 2 then
        data.targetId = checkString(vo.choiceTwoId)
        data.name = checkString(vo.choiceTwo)
    elseif index == 3 then
        data.targetId = checkString(vo.choiceThreeId)
        data.name = checkString(vo.choiceThree)
    end

    if checkNumber(data.targetId) == 0 then
        return nil
    end

    --vo = PhoneUtils.GetPhoneMessageVo(data.targetId)
    if isChat then
        vo = PhoneUtils.GetChatVoByTargetId(vo.messageId, data.targetId)
    else
        vo = PhoneUtils.GetMessageVoByTargetId(vo.messageId, data.targetId)
    end    
    if vo then
        data.desc = checkString(vo.text)
    end

    return data
end

