---GetChatInfoByRelay 获取角色的对话信息
---@param catId string 角色id
---@param talkContentId string 话题id
---@param replyIndexs string 回复数组
---@param targetMessageId string 迭代到的目标消息id
function PhoneUtils.GetChatInfoByRelay(catId, talkContentId, replyIndexs, targetMessageId)
    if not talkContentId or not replyIndexs then
        return {}
    end
    local t = {}
    local talkContentVo = PhoneUtils.GetPhoneTalkContentVo(talkContentId)
    if talkContentVo then 

    end

    local messageIds = PhoneUtils.GetTalkIds(checkString(talkContentId))
    if not messageIds or table.count(messageIds) <= 0 then
        return t
    end

    local count = 1
    --local vo = PhoneUtils.GetPhoneMessageVo(messageIds[1])
    local vo = PhoneUtils.GetPhoneMessageVo(PhoneUtils.GetTalkCountFirstId(talkContentId))

    local total = 0
    --如果还没有回复的数据
    while true do
        if not vo then
            break
        end

        local chatInfo = PhoneUtils.GetChatInfoByMessageId(vo.id, catId)
        if chatInfo then
            table.insert(t, chatInfo)
        end

        --如果此句是结束位
        if PhoneUtils.IsMessageIsEnd(vo.id) then
            table.insert(t, {
                messageId = 0,
                content = localize("当前聊天已结束"),
                type = Constants.PhoneChatType.End,
            })
            break
        --如果迭代到目标信息id位置
        elseif checkNumber(targetMessageId) == checkNumber(vo.id) then
            break
        --这句信息是没有玩家选择回复的 继续迭代
        elseif checkNumber(vo.jumpId) > 0 then
            vo = PhoneUtils.GetMessageVoByTargetId(vo.messageId, vo.jumpId)
        --这里需要拿到玩家选择回复的目标id
        else
            --如果拿超出了 选择的数量  直接跳出
            if count > table.count(replyIndexs) then
                break
            end
            local option = PhoneUtils.GetMessageSelection(vo.id, replyIndexs[count])
            vo = PhoneUtils.GetMessageVoByTargetId(vo.messageId, option.targetId)
            count = count + 1
        end 

        total = total + 1
        --防止死循环   大于100条数据被认为不正常
        if total > 100 then
            break
        end
    end

    return t
end

---GetStopMessageId 获取一句短信结束的id  只有自己发的短信才会有
---@param messageId string 短信id
function PhoneUtils.GetStopMessageId(messageId)
    local _id = checkString(messageId)
    local vo = PhoneUtils.GetPhoneMessageVo(_id)
    if not vo then
        return _id
    end
    --如果不是主动激活   直接返回现在的
    --if not PhoneUtils.IsTalkContentDrivingActive(vo.messageId) then
    --    return _id
    --end

    local total = 0

    while true do
        if not vo then
            break
        end
            
        --结束break
        if PhoneUtils.IsMessageIsEnd(vo.id) then
            break
        elseif checkNumber(vo.jumpId) > 0 then
            _id = vo.id
            vo = PhoneUtils.GetMessageVoByTargetId(vo.messageId, vo.jumpId)
        else
            _id = vo.id
            break
        end

        total = total + 1
        --防止死循环   大于100条数据被认为不正常
        if total > 100 then
            break
        end
    end
    return _id
end

---GetCatCurChatInfo 获取角色当前话题的对话信息
---@param catId string 角色id
function PhoneUtils.GetCatCurChatInfo(catId, targetMessageId)
    local phoneComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
    local t = phoneComp:GetCatCurChatInfo(catId)
    if not t then
        return {}
    end
    local curTalkContentId = t.curTalkContentId
    local replyIndexs = t.replyIndexs          --回复下标 数组

    --如果没有话题则没有开始对话
    if not curTalkContentId or checkNumber(curTalkContentId) == 0 then
        return {}
    end

    --该话题所有的对话
    local messageIds = PhoneUtils.GetTalkIds(curTalkContentId)
    if not messageIds or table.count(messageIds) <= 0 then
        return {}
    end

    local info = PhoneUtils.GetChatInfoByRelay(catId, curTalkContentId, replyIndexs, targetMessageId)
    return info
end

