---GetNextMessageVo 获取这条信息的下一句
---@param messageId string 短信id
---@param isChat boolean 是否时聊天
function PhoneUtils.GetNextMessageVo(messageId, isChat)
    local vo
    if isChat then
        vo = PhoneUtils.GetPhoneChattingVo(messageId)
    else
        vo = PhoneUtils.GetPhoneMessageVo(messageId)
    end

    if vo then
        if checkNumber(vo.jumpId) <= 0 then
            return nil
        end
        if isChat then
            vo = PhoneUtils.GetChatVoByTargetId(vo.messageId, vo.jumpId) 
        else
            vo = PhoneUtils.GetMessageVoByTargetId(vo.messageId, vo.jumpId) 
        end
    end
    return vo
end 

---IsHasNextMessage 判断这个会不会一直比比
---@param messageId string 短信id
function PhoneUtils.IsHasNextMessage(messageId)
    local vo = PhoneUtils.GetPhoneMessageVo(messageId)
    if vo then
        --有直接跳转
        if checkNumber(vo.jumpId) > 0 then
            return true
        end
    end
    return false
end 

---IsMessageIsEnd 该信息是否是结束标志位
---@param messageId string 短信id
function PhoneUtils.IsMessageIsEnd(messageId, isChat)
    local vo
    if isChat then
        vo = PhoneUtils.GetPhoneChattingVo(messageId)
    else
        vo = PhoneUtils.GetPhoneMessageVo(messageId)
    end
    if not vo then
        return false
    end

    return checkNumber(vo.isEnd) == 1
end


