---GetLikabilityLevelAllExp 获取当前等级的总经验
---@param catId string 角色id
---@param level string 等级
function PhoneUtils.GetLikabilityLevelAllExp(catId, level)
    level = checkNumber(level)
    
    local num = 0
    if level > 1 then
        for i = 1, level do
            local vo = PhoneUtils.GetLikabilityLevelVo(i)
            if vo then
                local targetLevelExp = checkNumber(vo.experience)
                num = num + targetLevelExp
            end
        end
    end
    return num
