---UpdateCatFavorabilityLevelAndExp 更新友好度等级和经验
---@param catId string 角色id
---@param newLevel string 等级
---@param exp string 经验值
function PhoneUtils.UpdateCatFavorabilityLevelAndExp(catId, newLevel, newExp, isDontShow, isFinishTopic, isDontaShowCommonUp)
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
    local oldLevel, oldExp = PhoneUtils.GetCatFavorabilityLevel(catId)
    comp:UpdateCatFavorabilityLevelAndExp(catId, newLevel, newExp)
    if newLevel > oldLevel then
        --PhoneUtils.ShowFavorabilityUpTips(catId, newExp - oldExp, newLevel, newExp)
        if not isDontShow then
            cs_coroutine.start(function()
                if isFinishTopic then 
                    coroutine.yield(WaitForSeconds(1))
                end
                CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIFeelingShopAscensionDialog, parameters = {catId = catId, oldLevel = oldLevel, newLevel = newLevel}}, {
                })
            end)
        end
        GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneReward, PhoneUtils.IsHasNotDrawReward() and 1 or 0)
    end
    if not isDontaShowCommonUp then
        cs_coroutine.start(PhoneUtils.ShowFavorabilityUpTips, catId, newExp - oldExp, newLevel, newExp)
    end
end

--展示好感度获得经验动画
function PhoneUtils.ShowFavorabilityUpTips(catId, upExp, newLevel, newExp)
    local uiRootTrans = CS.Engine.UI.UIModule.RootCanvas.transform

    local loader
    local go = uiRootTrans.transform:Find("FavorabilityPanel")
    if not go then

        if IsNull(loader) then
            loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Feeling/FavorabilityPanel.prefab", nil, true)
        end
        if loader.IsSuccess then
            go = CfUtils.InstantiateGo(loader.ResultObject, uiRootTrans)
            go.name = "FavorabilityPanel"
        end
    end
    
    local vo = PhoneUtils.GetCatVo(catId)
    if vo then
        CfUtils.FillText(go.transform:Find("ImgName/Text"), vo.name)
        CfUtils.FillText(go.transform:Find("ImgHeart/Text"), newLevel)
        CfUtils.FillText(go.transform:Find("TxtIncrease"), "+"..upExp)

        local skinCardId = PhoneUtils.GetRoleCurCardSkinId(catId)
        --[[
        local skinVo = CardConfMgr:GetInstance():GetCardDefaultSkinByCardId(skinCardId)
        if skinVo then
            CfUtils.FillImage(go.transform:Find("Mask/iconHead"), skinVo.buffHead)
        end
        ]]
        CfUtils.FillImage(go.transform:Find("Mask/iconHead"), CardConfMgr:GetInstance():GetCardDefaultBodyIconPath(skinCardId))

        
        local newAllExp = PhoneUtils.GetLikabilityLevelUpAllExp(newLevel)  
        local slider = go.transform:Find("sliderBg"):GetComponent("Slider")
        local curExp = (checkNumber(newExp) - PhoneUtils.GetLikabilityLevelAllExp(catId, newLevel))
        slider.value = curExp / newAllExp
        CfUtils.FillText(go.transform:Find("TxtCurrent"), curExp.."/"..newAllExp)
    end

    coroutine.yield(WaitForSeconds(2))
    if not isNull(loader) then
        loader:Release()
        loader = nil
    end
    CS.UnityEngine.GameObject.Destroy(go)
end 


