function PhoneUtils.GetOnlyChatInfoByRelay(catId, talkContentId, replyIndexs, targetMessageId)
    if not talkContentId or not replyIndexs then
        return {}
    end
    local t = {}

    local messageIds = PhoneUtils.GetChatIds(checkString(talkContentId))
    if not messageIds or table.count(messageIds) <= 0 then
        return t
    end

    local count = 1
    local vo = PhoneUtils.GetPhoneChattingVo(PhoneUtils.GetChatFirstId(talkContentId))

    local total = 0
    --如果还没有回复的数据
    while true do
        if not vo then
            break
        end

        local chatInfo = PhoneUtils.GetChatInfoByMessageId(vo.id, catId, true)
        if chatInfo then
            table.insert(t, chatInfo)
        end

        --如果此句是结束位
        if PhoneUtils.IsMessageIsEnd(vo.id, true) then
            table.insert(t, {
                messageId = 0,
                type = Constants.PhoneChatType.End,
            })
            break
        --如果迭代到目标信息id位置
        elseif checkNumber(targetMessageId) == checkNumber(vo.id) then
            break
        --这句信息是没有玩家选择回复的 继续迭代
        elseif checkNumber(vo.jumpId) > 0 then
            vo = PhoneUtils.GetChatVoByTargetId(vo.messageId, vo.jumpId)
        --这里需要拿到玩家选择回复的目标id
        else
            --如果拿超出了 选择的数量  直接跳出
            if count > table.count(replyIndexs) then
                break
            end
            local option = PhoneUtils.GetMessageSelection(vo.id, replyIndexs[count], true)
            vo = PhoneUtils.GetChatVoByTargetId(vo.messageId, option.targetId)
            count = count + 1
        end 

        total = total + 1
        --防止死循环   大于100条数据被认为不正常
        if total > 100 then
            break
        end
    end

    return t
end

