function PhoneUtils.GetRedPointState()
    local t = GameUtils.GetRedPointLocalAllGoods(Constants.RedPointLocalKey.Goodkey, Constants.IDType.PhoneTalkContent)
    --如果有话题
    if table.count(t) > 0 then
        for k, v in pairs(t) do
            --是电话
            if PhoneUtils.IsTalkCountIsTelephone(v) then
                return Constants.STATE.TELEPHONE
            end 
        end
        return Constants.STATE.MESSAGE
    else
        if PhoneUtils.IsHasNotDrawReward() then
            return Constants.STATE.REWARD
        end
    end
    return Constants.STATE.NONE
end

