--获取套餐消耗货币数量
function PhoneUtils.GetOrderConsumeGoodsNum(foodId, DrinkId)
    local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
    local num = 0
    local vo = CookingUtils.GetOrderFoodVo(foodId)
    if vo then 
        num = num + checkNumber(vo.coinNum)
    end
    vo = CookingUtils.GetOrderFoodVo(DrinkId)
    if vo then 
        num = num + checkNumber(vo.coinNum)
    end
    
    return checkInt(num)
end

