    for k, v in pairs(t1) do
        if checkNumber(roleId) == checkNumber(v) then
            --return checkNumber(t2[k])
        end
    end
    return checkNumber(vo.love)
end

--获取套餐好感度加成
function PhoneUtils.GetRoleFavorabilityAdd(roleId, foodId, drinkId)
    local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
    local isRoleFoodLike = PhoneUtils.IsRoleLikeFood(roleId, foodId) 
    local isRoleDrinkLike =  PhoneUtils.IsRoleLikeFood(roleId, drinkId)

    local voFood, voDrink = CookingUtils.GetOrderFoodVo(foodId), CookingUtils.GetOrderFoodVo(drinkId)
    if voFood and voDrink then
        local addNum = PhoneUtils.GetRoleAddNum(roleId, foodId) -- checkNumber(voFood.love) 
        local num = 0
        if isRoleFoodLike then
            addNum = addNum + addNum * PhoneUtils.GetOrderFavorabilityAdd()
        end
        num = num + addNum

        local addNum = PhoneUtils.GetRoleAddNum(roleId, drinkId)  --checkNumber(voDrink.love) 
        if isRoleDrinkLike then
            addNum = addNum + addNum * PhoneUtils.GetOrderFavorabilityAdd()
        end
        num = num + addNum

        return checkInt(num)
    end
    return 0
end

