--最大点餐次数
function PhoneUtils.GetMaxOrderTimes()
    ---@type StoreComponent
    local storeComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.StoreComponent)
    ---@type WelfareConstants
    local welfareConstants = import("Game.UI.Welfare.WelfareConstants")
    local isActive =  storeComp:IsMonthCardActive(welfareConstants.Configs[1].monthCardId)
    if not isActive then
        return PhoneUtils.GetMaxCfOrderTimes()
    end
    local StoreConstants = import('Game.UI.Store.StoreConstants')
    local num = PhoneUtils.GetMaxCfOrderTimes() + checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.CoffeeNum))
    return num
end

