---GetRoleTalk 获取角色说的话
---@param catId string 指定角色类型id
---@param type string 台词类型
function PhoneUtils.GetRoleTalkVo(catId, type)
    if checkNumber(type) <= 0 then
        return {}
    end
    print(catId, type)
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting2013, catId)
    if not t then
        return {}
    end
    local allTypes = {}
    for i, storeKey in pairs(t) do
        local v = string.split(storeKey, '_')
        local id, scene = v[1], v[2]
        if checkNumber(type) == checkNumber(scene) then
            table.insert(allTypes, checkNumber(id))
        end
    end
    local ind = math.random(table.count(allTypes))
    local id = allTypes[ind]
    return PhoneUtils.GetOrderTalkerVo(id)
end

---IsRoleLikeFood 是否是角色喜欢的食物
---@param roleId string 角色id
---@param foodId string 食物id
function PhoneUtils.IsRoleLikeFood(roleId, foodId, isUiShow)
    if isUiShow then
        if not PhoneUtils.IsUseFood(foodId) then
            return false
        end
    end
    --如果没有使用过直接返回


    local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
    local vo = CookingUtils.GetOrderFoodAddVo(foodId)
    if not vo then
        return false
    end
    local t = CfUtils.Split(vo.catLoveId)
    if not t then
        return false
    end
    for k, v in pairs(t) do
        if checkNumber(roleId) == checkNumber(v) then
            return true
        end
    end

    return false
    --[[
    local t = PhoneUtils.GetRoleLikeFoods(roleId)
    for k, v in pairs(t) do
        if checkNumber(foodId) == checkNumber(v) then
            return true
        end
    end
    return false
    ]]
end



