function PhoneUtils.GetAllDragTalkVo(roleId)
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting2522, roleId)
    local level, exp = PhoneUtils.GetCatFavorabilityLevel(roleId)

    local _t = {}
    local targetLove = 100
    for k, v in pairs(t) do
        local vo = PhoneUtils.GetOrderGiveFoodTalkVo(v)
        if vo then
            if checkNumber(vo.loveLv) >= checkNumber(level) then
                if not _t[checkString(vo.loveLv)] then
                    _t[checkString(vo.loveLv)] = {}
                end

                table.insert(_t[checkString(vo.loveLv)], vo)

                --找到当前好感度等级最近的区间
                if checkNumber(vo.loveLv) < targetLove then
                    targetLove = checkNumber(vo.loveLv)
                end
            end            
        end
    end
    local returnT = checkTable(_t[checkString(targetLove)])

    table.sort(returnT, function(a, b)
        return checkNumber(a.action) < checkNumber(b.action)
    end)
    return returnT
end

--约会是触摸人物的配置ID 
function PhoneUtils.GetRandomDragTalkVo(roleId, type)
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting2522, roleId)
    local level, exp = PhoneUtils.GetCatFavorabilityLevel(roleId)

    local _t = {}
    for k, v in pairs(t) do
        local vo = PhoneUtils.GetOrderGiveFoodTalkVo(v)
        if vo then
            if checkNumber(vo.loveLv) >= checkNumber(level) then
                table.insert(_t, vo)
            end            
        end
    end
    local random = math.random(table.count(_t))
    return _t[random]
end

