function PhoneUtils.CheckRole(cardId)
    local vo = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    if vo then
        local isUnlock = PhoneUtils.IsUnlockCatById(vo.characterId)
        if not isUnlock then
            PhoneUtils.AddRoleUnlockRedPoint(vo.characterId)
        end
    end
end

--增加一个角色解锁的小红点
local roleUnlockMap = {}
function PhoneUtils.AddRoleUnlockRedPoint(id)
    if not roleUnlockMap then
        roleUnlockMap = {}
    end

    if checkNumber(id) <= 0 then
        return
    end

    roleUnlockMap[checkString(id)] = 1
end

function PhoneUtils.IsRoleUnlockRedPoint(id)
    if not roleUnlockMap then
        return false
    end
    return checkNumber(roleUnlockMap[checkString(id)]) == 1
end

--
function PhoneUtils.RemoveRoleUnlockRedPoint(id)
    if not roleUnlockMap then
        return
    end
    roleUnlockMap[checkString(id)] = 0
end

return PhoneUtils